import numpy as np

def f(x, y, z):
    return 9*x*y*z - 2*(x+y+z)

u_vals = [4/9, (50 + np.sqrt(2176)) / 162, (50 - np.sqrt(2176)) / 162]
results = []
for u in u_vals:
    x_pos = np.sqrt(u)
    x_neg = -np.sqrt(u)
    for x in [x_pos, x_neg]:
        z = -(27*x**3 - 11*x)/2
        # Check if 2x^2 + z^2 = 1
        if abs(2*x**2 + z**2 - 1) < 1e-6:
            results.append(f(x, x, z))
            results.append(f(x, z, x))
            results.append(f(z, x, x))

print(f"Critical values: {sorted(list(set(np.round(results, 10))))}")

